export function getCustomerTransactions(accountNumber: string): TransactionRecord[] {
  return CUSTOMER_TRANSACTIONS.filter((t) => t.customer_id === accountNumber);
}

export function getLatestBalance(accountNumber: string): number {
  const txs = getCustomerTransactions(accountNumber);
  if (txs.length === 0) return 0;
  return txs[txs.length - 1].running_balance;
}
